use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Updates the `disambiguator` field of the corresponding `ExpnData`"] # [doc = " such that the `Fingerprint` of the `ExpnData` does not collide with"] # [doc = " any other `ExpnIds`."] # [doc = ""] # [doc = " This method is called only when an `ExpnData` is first associated"] # [doc = " with an `ExpnId` (when the `ExpnId` is initially constructed, or via"] # [doc = " `set_expn_data`). It is *not* called for foreign `ExpnId`s deserialized"] # [doc = " from another crate's metadata - since `ExpnHash` includes the stable crate id,"] # [doc = " collisions are only possible between `ExpnId`s within the same crate."] fn update_disambiguator (expn_data : & mut ExpnData , mut ctx : impl HashStableContext) -> ExpnHash { assert_eq ! (expn_data . disambiguator , 0 , "Already set disambiguator for ExpnData: {expn_data:?}") ; assert_default_hashing_controls (& ctx , "ExpnData (disambiguator)") ; let mut expn_hash = expn_data . hash_expn (& mut ctx) ; let disambiguator = HygieneData :: with (| data | { let disambig = data . expn_data_disambiguators . entry (expn_hash) . or_default () ; let disambiguator = * disambig ; * disambig += 1 ; disambiguator }) ; if disambiguator != 0 { debug ! ("Set disambiguator for expn_data={:?} expn_hash={:?}" , expn_data , expn_hash) ; expn_data . disambiguator = disambiguator ; expn_hash = expn_data . hash_expn (& mut ctx) ; # [cfg (debug_assertions)] HygieneData :: with (| data | { assert_eq ! (data . expn_data_disambiguators . get (& expn_hash) , None , "Hash collision after disambiguator update!" ,) ; }) ; } ExpnHash :: new (ctx . def_path_hash (LOCAL_CRATE . as_def_id ()) . stable_crate_id () , expn_hash) }
}